#!/bin/bash
# Task 181-w24-kitfull -- meshsim sim/ WORKER24 (branch sim-w24; P6, inventory D8).
# The sort's measurement kit at full size, a sample: the C++ kit (sim/tests/sort/kit: sort_test, sort_summary; built
# here with clang release) and v1.3's kit assembled from sim/ref (oracle/ref/sortkit.sh), each on jobs-sample.txt at
# 64 x 65,536 (p4/uniform-k128 direct, p4/sorted-kv32 LB, p4/reverse-k128 TH, p4/trace100-30-k128 BT, shuf/uniform-k128
# shuffled), side by side. Compared: every run's checks; the CSVs (every column but the five peaks: W20's PhaseLog is
# pending) and the logs (but the peak lines and the inputs line's first field); sort_compare's report; p4/uniform-k128's
# TOTAL against golden-m2's sort64k (1,229,687). Key sets from pipeline/keys' KeyGen (a JDK here), checked against the
# kits' HASHES. Not timing (wall times recorded only); the machine recorded (D21). From an embedded kit. Writes only
# results/181-w24-kitfull/. Scratch in /tmp, removed first and at the end. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/181-w24-kitfull; mkdir -p "$RES"
W=/tmp/w24-181; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "ea11042ee30480eb25390f08fd558133f8e4b832c24d2d37851582f38faa5607" ] || { echo "kit sha256 mismatch (want ea11042ee30480eb25390f08fd558133f8e4b832c24d2d37851582f38faa5607)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
S=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
{ echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs"; lscpu | grep -E '^(Model name|Thread|Core|Socket|CPU max MHz)'
  grep MemTotal /proc/meminfo; java -version 2>&1 | head -1; clang++ --version | head -1; } | tee "$RES/machine.txt"
NP=$(nproc); J=$(( NP >= 12 ? 5 : (NP > 2 ? NP / 2 : 1) ))
# the C++ kit (assemble.sh builds sort_test and sort_summary), its key sets made by run.sh with KeyGen (a JDK here)
(cd "$S" && bash tests/sort/kit/assemble.sh "$W/cpp" > "$RES/assemble.out" 2>&1) || { cat "$RES/assemble.out"; verdict assemble FAIL; echo FAILED; exit 1; }
cp "$S/tests/sort/kit/jobs-sample.txt" "$W/cpp/"
( cd "$W/cpp" && ./run.sh -n 65536 -j $J -J jobs-sample.txt > "$RES/cpp-run.out" 2>&1 ) & cp=$!
# v1.3's kit from ref, the same jobs
( bash "$S/oracle/ref/sortkit.sh" "$W/ref" -n 65536 -j $J -m 6g -J "$S/tests/sort/kit/jobs-sample.txt" > "$RES/ref-run.out" 2>&1 ) & rp=$!
wait $cp; crc=$?; wait $rp; rrc=$?
tail -8 "$RES/cpp-run.out"; tail -8 "$RES/ref-run.out"
C=$W/cpp/results; R=$W/ref/kit/results
for d in cpp:$C ref:$R; do (cd "${d#*:}" && tar --sort=name --mtime=@0 --owner=0 --group=0 -czf "$RES/${d%%:*}-results.tgz" .) 2>/dev/null; done
n=$(ls "$C"/*.csv 2>/dev/null | grep -v -e phases -e all.csv | wc -l)
bad=$(for l in "$C"/*.log; do grep -q 'SortTest.*: [0-9]* passed, 0 failed' "$l" || echo "$l"; done | wc -l)
[ $crc = 0 ] && [ "$n" = 5 ] && [ "$bad" = 0 ] && verdict cpp-runs PASS || verdict cpp-runs FAIL
nr=$(ls "$R"/*.csv 2>/dev/null | grep -v -e phases -e all.csv | wc -l)
[ $rrc = 0 ] && [ "$nr" = 5 ] && verdict ref-runs PASS || verdict ref-runs FAIL
# every run's CSV (peaks aside) and log (peak lines and the simulator's field aside) against v1.3's
ok=1
for f in "$C"/*.csv; do b=$(basename "$f"); case $b in all.csv|*.phases.csv) continue;; esac
  if cmp -s <(cut -d, -f1-14,20 "$f") <(cut -d, -f1-14,20 "$R/$b"); then echo "SAME csv $b (peaks aside)"; else echo "DIFF csv $b"; ok=0; fi
  l=${b%.csv}.log
  m() { grep -v -e 'GATHER queue peak' -e 'peaks in' -e 'PENDING (W20' "$1" | sed -E 's/^(inputs: )[^ ]+/\1<sim>/'; }
  if cmp -s <(m "$C/$l") <(m "$R/$l"); then echo "SAME log $l (peak lines aside)"; else echo "DIFF log $l"; diff <(m "$C/$l") <(m "$R/$l") | head -6; ok=0; fi
  # the TOTAL lines (they hold the GATHER queue peak) up to it
  a=$(grep TOTAL "$C/$l" | sed 's/GATHER queue peak.*//'); r=$(grep TOTAL "$R/$l" | sed 's/GATHER queue peak.*//')
  [ "$a" = "$r" ] && echo "SAME TOTAL $l" || { echo "DIFF TOTAL $l"; ok=0; }
done | tee "$RES/compare.txt"
grep -q '^DIFF' "$RES/compare.txt" && verdict cpp-equals-ref FAIL || verdict cpp-equals-ref PASS
"$S/build/clang-release/sort_compare" "$C" "$R" "$RES/sort_compare.md" > /dev/null 2>&1; head -12 "$RES/sort_compare.md"
t=$(grep -h 'TOTAL' "$C/p4_uniform-k128.log" | grep -o 'TOTAL [0-9,]*' | tr -d ',')
[ "$t" = "TOTAL 1229687" ] && verdict uniform-k128-vs-sort64k PASS || { echo "uniform-k128: $t"; verdict uniform-k128-vs-sort64k FAIL; }
grep -h 'exit' "$RES/cpp-run.out" "$RES/ref-run.out" > "$RES/walltimes.txt"
(cd "$RES" && sha256sum $(find . -type f ! -name SHA256SUMS ! -name run.log | sort) > SHA256SUMS)
echo; cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo DONE; exit 0; } || { echo FAILED; exit 1; }
